import torch
import torch.nn as nn
import torch.nn.functional as F
class TLCompactRecipe(nn.Module):
    def __init__(self):
        super().__init__()
        self.embed=nn.Embedding(8192,64)
        self.token=nn.TransformerEncoder(nn.TransformerEncoderLayer(d_model=64,nhead=4,dim_feedforward=128,batch_first=True),num_layers=1)
        self.conv=nn.Sequential(nn.Conv2d(3,16,3,padding=1),nn.GELU(),nn.Conv2d(16,16,3,padding=1),nn.GELU(),nn.AdaptiveAvgPool2d((4,4)))
        self.conv_head=nn.Linear(256,64)
        self.seq=nn.GRU(32,64,batch_first=True)
        self.flat=nn.Linear(64,64)
        self.head=nn.Sequential(nn.Linear(64,64),nn.GELU(),nn.Linear(64,16))
    def _first_tensor(self,x):
        if isinstance(x,(list,tuple)):
            for item in x:
                if torch.is_tensor(item):
                    return item
            return torch.zeros(1,16)
        return x if torch.is_tensor(x) else torch.zeros(1,16)
    def _fit2(self,y,n):
        y=y.reshape(y.shape[0] if y.ndim else 1,-1)
        if y.shape[1]<n:
            y=F.pad(y,(0,n-y.shape[1]))
        return y[:,:n]
    def forward(self,x):
        x=self._first_tensor(x)
        if not x.dtype.is_floating_point and not x.dtype.is_complex:
            tok=x.long().reshape(x.shape[0] if x.ndim else 1,-1).clamp(min=0,max=8191)
            return self.head(self.token(self.embed(tok)).mean(dim=1))
        y=x.float()
        if y.ndim>=4:
            if y.shape[1]<3:
                y=y.repeat(1,3//y.shape[1]+1,*([1]*(y.ndim-2)))[:,:3]
            if y.ndim>4:
                y=y.flatten(2,-2)
            return self.head(self.conv_head(self.conv(y[:,:3]).flatten(1)))
        if y.ndim==3:
            b,t=y.shape[0],y.shape[1]
            z=self._fit2(y.reshape(b*t,-1),32).reshape(b,t,32)
            h,_=self.seq(z)
            return self.head(h[:,-1])
        return self.head(self.flat(self._fit2(y,64)))
TLCompactRecipe.__module__='torchlens_menagerie'
model=TLCompactRecipe()
", globals());

