import torch.nn as nn
import torch.nn.functional as F

class PixelNorm(nn.Module):
    def forward(self, x):
        return x / torch.sqrt(x.pow(2).mean(1, keepdim=True) + 1e-8)

class EConv(nn.Conv2d):
    def forward(self, x):
