class UNet3Plus(nn.Module):
    def __init__(self, in_ch=3, n_cls=2, cat_ch=64):
        super().__init__()
        chs=[64,128,256,512,1024]; hcat=5*cat_ch
        def enc(ic,oc): return nn.Sequential(nn.Conv2d(ic,oc,3,padding=1),nn.BatchNorm2d(oc),nn.ReLU(),nn.Conv2d(oc,oc,3,padding=1),nn.BatchNorm2d(oc),nn.ReLU())
        self.e = nn.ModuleList([enc(in_ch if i==0 else chs[i-1], chs[i]) for i in range(5)])
        self.pool = nn.MaxPool2d(2)
        self.fine_lats = nn.ModuleList([nn.ModuleList([nn.Sequential(nn.Conv2d(chs[s],cat_ch,3,padding=1),nn.BatchNorm2d(cat_ch),nn.ReLU()) for s in range(d+1)]) for d in range(4)])
        self.coarse_from_dec = nn.ModuleList([nn.ModuleList([nn.Sequential(nn.Conv2d(hcat,cat_ch,3,padding=1),nn.BatchNorm2d(cat_ch),nn.ReLU()) for _ in range(3-d)]) for d in range(3)])
        self.coarse_from_e4 = nn.ModuleList([nn.Sequential(nn.Conv2d(chs[4],cat_ch,3,padding=1),nn.BatchNorm2d(cat_ch),nn.ReLU()) for _ in range(4)])
        self.decs = nn.ModuleList([nn.Sequential(nn.Conv2d(hcat,hcat,3,padding=1),nn.BatchNorm2d(hcat),nn.ReLU()) for _ in range(4)])
        self.out = nn.Conv2d(hcat, n_cls, 1)
    def forward(self, x):
        e=[]; inp=x
        for i,blk in enumerate(self.e):
            inp=blk(inp); e.append(inp)
            if i<4: inp=self.pool(inp)
        dec_feats=[]
        for d in range(3,-1,-1):
            tgt=e[d].shape[-2:]; parts=[]
            for s in range(d+1):
                src = e[s] if s==d else F.adaptive_avg_pool2d(e[s],tgt)
                parts.append(self.fine_lats[d][s](src))
            if d==3:
                src = F.interpolate(e[4],size=tgt,mode='bilinear',align_corners=False)
                parts.append(self.coarse_from_e4[3](src))
            else:
