    def __init__(self, n_users=1000, n_items=5000, emb_size=64, layers=(64,64,64)):
        super().__init__()
        self.user_emb = nn.Embedding(n_users, emb_size)
        self.item_emb = nn.Embedding(n_items, emb_size)
