        self.flat=nn.Linear(64,64)
        self.head=nn.Sequential(nn.Linear(64,64),nn.GELU(),nn.Linear(64,16))
    def _first_tensor(self,x):
        if isinstance(x,(list,tuple)):
            for item in x:
                if torch.is_tensor(item):
                    return item
            return torch.zeros(1,16)
        return x if torch.is_tensor(x) else torch.zeros(1,16)
