import torch
import torch.nn as nn
from torch_geometric.nn import MetaLayer
class EdgeModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(52, 16), nn.ReLU(), nn.Linear(16, 4))
    def forward(self, src, dst, edge_attr, u, batch):
        return self.net(torch.cat([src, dst, edge_attr, u[batch]], dim=-1))
class NodeModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(36, 16), nn.ReLU(), nn.Linear(16, 16))
    def forward(self, x, edge_index, edge_attr, u, batch):
        row, col = edge_index
        agg = x.new_zeros(x.size(0), edge_attr.size(-1))
        agg.index_add_(0, col, edge_attr)
        deg = x.new_zeros(x.size(0), 1)
        deg.index_add_(0, col, x.new_ones(col.numel(), 1))
        agg = agg / deg.clamp_min(1.0)
        return self.net(torch.cat([x, agg, u[batch]], dim=-1))
class GlobalModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(36, 16), nn.ReLU(), nn.Linear(16, 16))
    def forward(self, x, edge_index, edge_attr, u, batch):
        graphs = int(batch.max().item()) + 1
        node_mean = x.new_zeros(graphs, x.size(-1))
        node_mean.index_add_(0, batch, x)
        node_deg = x.new_zeros(graphs, 1)
        node_deg.index_add_(0, batch, x.new_ones(x.size(0), 1))
        node_mean = node_mean / node_deg.clamp_min(1.0)
        edge_batch = batch[edge_index[1]]
        edge_mean = edge_attr.new_zeros(graphs, edge_attr.size(-1))
        edge_mean.index_add_(0, edge_batch, edge_attr)
        edge_deg = edge_attr.new_zeros(graphs, 1)
        edge_deg.index_add_(0, edge_batch, edge_attr.new_ones(edge_attr.size(0), 1))
        edge_mean = edge_mean / edge_deg.clamp_min(1.0)
        return self.net(torch.cat([u, node_mean, edge_mean], dim=-1))
class MetaLayerWrapper(nn.Module):
    def __init__(self):
        super().__init__()
        self.core = MetaLayer(EdgeModel(), NodeModel(), GlobalModel())
        self.register_buffer('x_graph', torch.linspace(-1.0, 1.0, 64).reshape(4, 16))
        self.register_buffer('edge_index', torch.tensor([[0, 1, 2, 3, 0, 2, 1, 3], [1, 2, 3, 0, 2, 0, 3, 1]], dtype=torch.long))
